const body = $input.item.json.body;
const sender = body.sender || body.from || 'Unknown';
const message = body.message || body.text || '';
const timestamp = body.timestamp || new Date().toISOString();

// Clean phone number formatting
const cleanSender = sender.replace(/[^\d+]/g, '');

return [{
  json: {
    sender,
    cleanSender,
    message,
    timestamp,
    promptText: `Incoming text message:\nFrom: ${sender}\nTime: ${timestamp}\nMessage: ${message}`
  }
}];

const response = $input.item.json;
const smsData = $('Extract SMS Data').item.json;
let parsed;

try {
  parsed = JSON.parse(response.content[0].text);
} catch (e) {
  const match = response.content[0].text.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    parsed = { relevant: false, category: 'unknown', summary: 'Could not parse', priority: 'low', has_event: false, suggested_actions: [], needs_response: false };
  }
}

return [{
  json: {
    ...smsData,
    ...parsed
  }
}];

const data = $input.item.json;

const categoryEmoji = {
  invitation: '\uD83C\uDF89',
  schedule_change: '\uD83D\uDD04',
  reminder: '\u23F0',
  info: '\u2139\uFE0F',
  school: '\uD83C\uDFEB',
  sports: '\u26BD',
  medical: '\uD83C\uDFE5',
  social: '\uD83C\uDF7B'
};

const priorityEmoji = { high: '\u2757', medium: '\u2755', low: '' };

let message = `${priorityEmoji[data.priority] || ''}\uD83D\uDCF1 *Text from ${data.sender}*\n\n`;
message += `${data.summary}\n`;

if (data.has_event && data.event_details) {
  const e = data.event_details;
  message += `\n\uD83D\uDCC5 *Event:* ${e.title || 'TBD'}\n`;
  if (e.date) message += `\uD83D\uDCC6 ${e.date}`;
  if (e.time) message += ` at ${e.time}`;
  message += '\n';
  if (e.location) message += `\uD83D\uDCCD ${e.location}\n`;
}

// Build action buttons as text prompts
if (data.suggested_actions && data.suggested_actions.length > 0) {
  message += '\n*Want me to:*\n';
  const actionLabels = {
    add_to_calendar: '\uD83D\uDCC5 Add to calendars',
    notify_josh: '\uD83D\uDCE4 Notify Josh',
    rsvp: '\u2709\uFE0F RSVP',
    set_reminder: '\u23F0 Set a reminder',
    none: ''
  };
  data.suggested_actions.forEach(function(action) {
    if (action !== 'none' && actionLabels[action]) {
      message += `  \u2022 ${actionLabels[action]}\n`;
    }
  });
  message += '\n_Reply with what you\'d like me to do._';
}

if (data.needs_response) {
  message += `\n\n\u26A0\uFE0F _${data.sender} is expecting a reply`;
  if (data.response_deadline) message += ` by ${data.response_deadline}`;
  message += '_';
}

return [{
  json: {
    message,
    to: 'YOUR_PHONE_NUMBER',
    originalData: data
  }
}];
